<?php

declare(strict_types=1);

namespace OCA\Phos\Service\Sword;

/**
 * A sword versification system (tables in v11n.json, generated by
 * dev/gen_v11n.py) and the verse → index arithmetic of
 * VersificationMgr::System (one module heading, then per testament one
 * testament heading, per book a book heading, per chapter a chapter heading).
 */
final class Versification {
	/** @var array<string, list<array{osis:string,name:string,t:int,v:list<int>}>>|null */
	private static ?array $tables = null;
	/** @var array<string, self> */
	private static array $loaded = [];

	/** @var list<array{osis:string,name:string,t:int,v:list<int>}> */
	public readonly array $books;
	/** @var array<string, int> osis → position in $books */
	private array $byOsis = [];
	/** @var list<list<int>> per book: index of each chapter heading */
	private array $chapterOffsets = [];
	private int $ntStart = 0;

	private function __construct(public readonly string $name, array $books) {
		$this->books = $books;
		$offset = 1;    // module heading at 0, testament heading at 1
		$testament = 1;
		foreach ($books as $i => $b) {
			if ($b['t'] !== $testament) {
				$this->ntStart = $offset;
				$offset++;  // NT testament heading
				$testament = 2;
			}
			$this->byOsis[$b['osis']] = $i;
			$offset++;      // book heading
			$pre = [];
			foreach ($b['v'] as $max) {
				$offset++;  // chapter heading
				$pre[] = $offset;
				$offset += $max;
			}
			$this->chapterOffsets[] = $pre;
		}
		if ($testament === 1) {
			$this->ntStart = $offset;
		}
	}

	/** @return list<string> */
	public static function names(): array {
		return array_keys(self::tables());
	}

	private static function tables(): array {
		return self::$tables ??= json_decode((string)file_get_contents(__DIR__ . '/v11n.json'), true);
	}

	/** Unknown names fall back to KJV, like sword does. */
	public static function get(string $name): self {
		$t = self::tables();
		if (!isset($t[$name])) {
			$name = 'KJV';
		}
		return self::$loaded[$name] ??= new self($name, $t[$name]);
	}

	public function bookIndex(string $osis): ?int {
		return $this->byOsis[$osis] ?? null;
	}

	public function chapterCount(int $book): int {
		return count($this->books[$book]['v'] ?? []);
	}

	public function verseCount(int $book, int $chapter): int {
		return $this->books[$book]['v'][$chapter - 1] ?? 0;
	}

	/**
	 * Testament (1/2) and index within that testament's files.
	 * chapter 0 = book introduction, verse 0 = chapter introduction.
	 * @return array{0:int,1:int}|null
	 */
	public function locate(int $book, int $chapter, int $verse): ?array {
		$pre = $this->chapterOffsets[$book] ?? null;
		if ($pre === null || $chapter < 0 || $chapter > count($pre) || $verse < 0) {
			return null;
		}
		if ($chapter > 0 && $verse > $this->books[$book]['v'][$chapter - 1]) {
			return null;
		}
		$offset = $chapter === 0 ? $pre[0] - 1 : $pre[$chapter - 1];
		$offset += $verse;
		$t = $this->books[$book]['t'];
		return [$t, $t === 1 ? $offset : $offset - $this->ntStart];
	}
}
